@import "tailwindcss" source(none);
@import "tw-animate-css";
@import "./tokens.css";
@import "@fontsource-variable/geist";

@source "../components";
@source "../blocks";
@source "../product";

@layer base {
  * {
    border-color: var(--hairline);
  }

  html,
  body,
  #root {
    min-height: 100%;
  }

  body {
    margin: 0;
    background: var(--surface-0);
    color: var(--ink);
    font-family: var(--font-sans-stack);
    font-size: 14px;
    font-weight: 400;
    line-height: 1.45;
    text-rendering: optimizeLegibility;
    -webkit-font-smoothing: antialiased;
  }

  button,
  input,
  textarea,
  select {
    font: inherit;
  }

  button:not(:disabled),
  [role="button"]:not([aria-disabled="true"]) {
    cursor: default;
  }

  ::selection {
    background: var(--overlay-selected);
  }

  html {
    @apply font-sans;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

:root {
  color-scheme: dark;

  --surface-0: oklch(0.145 0.003 260);
  --surface-1: oklch(0.18 0.004 260);
  --surface-2: oklch(0.225 0.005 260);
  --surface-sunken: oklch(0.115 0.003 260);
  --surface-inverted: oklch(0.97 0.002 260);

  --ink: oklch(0.97 0.002 260);
  --ink-2: oklch(0.97 0.002 260 / 0.72);
  --ink-3: oklch(0.97 0.002 260 / 0.56);
  --ink-4: oklch(0.97 0.002 260 / 0.42);
  --ink-inverted: oklch(0.18 0.004 260);

  --overlay-hover: oklch(1 0 0 / 0.06);
  --overlay-press: oklch(0 0 0 / 0.16);
  --overlay-selected: oklch(0.72 0.13 250 / 0.18);
  --hairline-w: 1px;
  --hairline: oklch(1 0 0 / 0.16);

  --accent-solid: oklch(0.52 0.15 255);
  --block-solid: oklch(0.485 0.185 26);
  --on-solid: oklch(0.99 0 0);
  --accent-contrast: oklch(0.78 0.11 250);
  --ring: var(--accent-contrast);
  --work-contrast: oklch(0.86 0.14 152);
  --need-contrast: oklch(0.845 0.115 70);
  --block-contrast: oklch(0.735 0.155 26);
  --done-contrast: oklch(0.8 0.1 215);
  --idle-contrast: oklch(0.72 0.01 260);
  --accent-soft: oklch(0.24 0.055 255);
  --work-soft: oklch(0.245 0.045 152);
  --need-soft: oklch(0.255 0.046 70);
  --block-soft: oklch(0.25 0.052 26);
  --done-soft: oklch(0.245 0.042 215);
  --idle-soft: oklch(0.235 0.006 260);

  --shade-1: oklch(0 0 0 / 0.3);
  --shade-2: oklch(0 0 0 / 0.45);
  --shade-3: oklch(0 0 0 / 0.6);
  --elev-ring: inset 0 0 0 var(--hairline-w) var(--hairline);
  --elev-raised:
    inset 0 0 0 var(--hairline-w) var(--hairline),
    0 1px 2px -1px var(--shade-1),
    0 4px 10px -4px var(--shade-2);
  --elev-overlay:
    inset 0 0 0 var(--hairline-w) var(--hairline),
    0 8px 24px -8px var(--shade-2),
    0 20px 64px -12px var(--shade-3);

  --font-sans-stack: "Geist Variable", sans-serif;
  --font-mono-stack: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  --font-heading: var(--font-sans-stack);

  --radius-1: 6px;
  --radius-2: 8px;
  --radius-3: 10px;
  --radius-4: 12px;
  --radius: var(--radius-2);
  --control-sm: 28px;
  --control: 32px;
  --chrome: 48px;
  --toolbar: 40px;
  --column-header: 32px;
  --status-band: 32px;
  --row: 36px;
  --row-decision: 56px;
  --row-task: 52px;
  --rail: 275px;
  --assistant-rail: 360px;
  --split-list: 340px;
  --detail: 320px;
  --palette: 672px;
  --measure-prose: 560px;
  --traffic-light-inset: 76px;

  --duration-color: 120ms;
  --duration-sidebar: 140ms;
  --duration-overlay-enter: 180ms;
  --duration-overlay-exit: 120ms;
  --ease-enter: cubic-bezier(0.2, 0, 0, 1);
  --ease-exit: cubic-bezier(0.4, 0, 1, 1);
  --ease-shape: cubic-bezier(0.42, 0, 0.58, 1);

  /* shadcn semantic aliases. The Humanctl palette remains authoritative. */
  --background: var(--surface-0);
  --foreground: var(--ink);
  --card: var(--surface-1);
  --card-foreground: var(--ink);
  --popover: var(--surface-2);
  --popover-foreground: var(--ink);
  --primary: var(--accent-solid);
  --primary-foreground: var(--on-solid);
  --secondary: var(--surface-1);
  --secondary-foreground: var(--ink);
  --muted: var(--surface-sunken);
  --muted-foreground: var(--ink-3);
  --accent: var(--surface-2);
  --accent-foreground: var(--ink);
  --destructive: var(--block-solid);
  --border: var(--hairline);
  --input: var(--hairline);
  --sidebar: var(--surface-1);
  --sidebar-foreground: var(--ink);
  --sidebar-primary: var(--accent-solid);
  --sidebar-primary-foreground: var(--on-solid);
  --sidebar-accent: var(--overlay-hover);
  --sidebar-accent-foreground: var(--ink);
  --sidebar-border: var(--hairline);
  --sidebar-ring: var(--ring);
}

.light {
  color-scheme: light;
  --surface-0: oklch(0.985 0.002 260);
  --surface-1: oklch(1 0 0);
  --surface-2: oklch(1 0 0);
  --surface-sunken: oklch(0.955 0.003 260);
  --surface-inverted: oklch(0.205 0.004 260);
  --ink: oklch(0.205 0.004 260);
  --ink-2: oklch(0.205 0.004 260 / 0.76);
  --ink-3: oklch(0.205 0.004 260 / 0.62);
  --ink-4: oklch(0.205 0.004 260 / 0.48);
  --ink-inverted: oklch(0.985 0.002 260);
  --overlay-hover: oklch(0.205 0.004 260 / 0.045);
  --overlay-press: oklch(0 0 0 / 0.06);
  --overlay-selected: oklch(0.52 0.15 255 / 0.12);
  --hairline: oklch(0.205 0.004 260 / 0.13);
  --shade-1: oklch(0.3 0.01 260 / 0.06);
  --shade-2: oklch(0.3 0.01 260 / 0.1);
  --shade-3: oklch(0.3 0.01 260 / 0.16);
  --accent-contrast: oklch(0.46 0.14 255);
  --ring: var(--accent-contrast);
  --work-contrast: oklch(0.4 0.095 152);
  --need-contrast: oklch(0.47 0.1 70);
  --block-contrast: oklch(0.5 0.165 26);
  --done-contrast: oklch(0.445 0.078 215);
  --idle-contrast: oklch(0.47 0.008 260);
  --accent-soft: oklch(0.94 0.028 255);
  --work-soft: oklch(0.935 0.032 152);
  --need-soft: oklch(0.94 0.034 70);
  --block-soft: oklch(0.935 0.03 26);
  --done-soft: oklch(0.935 0.028 215);
  --idle-soft: oklch(0.945 0.004 260);
}

@media (min-resolution: 2dppx) {
  :root {
    --hairline-w: 0.5px;
  }
}

@theme inline {
  --font-sans: var(--font-sans-stack);
  --font-mono: var(--font-mono-stack);
  --color-background: var(--surface-0);
  --color-foreground: var(--ink);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-input: var(--input);
  --color-surface: var(--surface-1);
  --color-overlay: var(--surface-2);
  --color-sunken: var(--surface-sunken);
  --color-inverted: var(--surface-inverted);
  --color-ink: var(--ink);
  --color-ink-2: var(--ink-2);
  --color-ink-3: var(--ink-3);
  --color-ink-4: var(--ink-4);
  --color-ink-inverted: var(--ink-inverted);
  --color-primary: var(--accent-solid);
  --color-primary-foreground: var(--on-solid);
  --color-destructive: var(--block-solid);
  --color-destructive-foreground: var(--on-solid);
  --color-border: var(--hairline);
  --color-ring: var(--accent-contrast);
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);
  --color-work: var(--work-contrast);
  --color-need: var(--need-contrast);
  --color-block: var(--block-contrast);
  --color-done: var(--done-contrast);
  --color-idle: var(--idle-contrast);
  --color-accent-soft: var(--accent-soft);
  --color-work-soft: var(--work-soft);
  --color-need-soft: var(--need-soft);
  --color-block-soft: var(--block-soft);
  --color-done-soft: var(--done-soft);
  --color-idle-soft: var(--idle-soft);
  --radius-sm: var(--radius-1);
  --radius-md: var(--radius-2);
  --radius-lg: var(--radius-3);
  --radius-xl: var(--radius-4);
}

/*
 * shadcn/typeset
 * https://ui.shadcn.com/docs/typeset.
 */

@layer components {
  .typeset {
    --typeset-font-body: inherit;
    --typeset-font-heading: var(--font-heading);
    --typeset-font-mono: var(--font-mono);
    --typeset-size: 1em;
    --typeset-leading: 1.75;
    --typeset-flow: 1.25em;
  }
}

@layer components {
  .typeset {
    font-family: var(--typeset-font-body);
    font-size: calc(var(--typeset-size) * 1.125);
    line-height: var(--typeset-leading);
    color: var(--color-foreground, currentColor);
    overflow-wrap: break-word;
    margin-trim: block-start;

    @media (min-width: 48rem), print {
      font-size: var(--typeset-size);
    }

    --typeset-muted: var(
      --color-muted-foreground,
      color-mix(in oklab, currentColor 60%, transparent)
    );
    --typeset-rule: var(
      --color-border,
      color-mix(in oklab, currentColor 20%, transparent)
    );
  }

  .typeset
    *:not(
      :where(
        .not-typeset,
        [data-not-typeset],
        .not-typeset *,
        [data-not-typeset] *
      )
    ) {
    /* Paragraphs. */
    &:where(p) {
      margin-block-start: var(--typeset-flow);
      margin-block-end: 0;
    }

    /* Headings. */
    &:where(h1, h2, h3, h4, h5, h6) {
      color: var(--color-foreground, currentColor);
      font-family: var(--typeset-font-heading);
      font-weight: 600;
      margin-block-end: 0;
    }
    &:where(h1) {
      font-size: 1.75em;
      line-height: 1.3;
      margin-block-start: var(--typeset-flow);
    }
    &:where(h2) {
      font-size: 1.25em;
      line-height: 1.4;
      margin-block-start: calc(var(--typeset-flow) * 1.4);
    }
    &:where(h3) {
      font-size: 1.125em;
      line-height: 1.45;
      margin-block-start: var(--typeset-flow);
    }
    &:where(h4) {
      font-size: 1em;
      line-height: 1.5;
      margin-block-start: var(--typeset-flow);
    }
    &:where(h5) {
      font-size: 0.875em;
      line-height: 1.5;
      font-weight: 500;
      color: var(--typeset-muted);
      margin-block-start: calc(var(--typeset-flow) / 0.875);
    }
    &:where(h6) {
      font-size: 0.8125em;
      line-height: 1.5;
      font-weight: 500;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--typeset-muted);
      margin-block-start: calc(var(--typeset-flow) / 0.8125);
    }
    /* Anchors. */
    &:where([id]) {
      scroll-margin-block-start: var(--typeset-flow);
    }

    /* Headings own the space below them. */
    &:where(h1 + *, h2 + *, h3 + *, h4 + *, h5 + *, h6 + *) {
      margin-block-start: 1em;
    }
    &:where(:is(h1, h2, h3, h4) :is(code)) {
      font-size: 0.9em;
    }

    /* Links. */
    &:where(a) {
      color: inherit;
      font-weight: 500;
      text-decoration-line: underline;
      text-decoration-color: color-mix(in oklab, currentColor 30%, transparent);
    }
    &:where(a:hover) {
      text-decoration-color: currentColor;
    }
    &:where(a:focus-visible) {
      outline: 2px solid var(--color-ring, currentColor);
      outline-offset: 2px;
      border-radius: 0.125em;
    }
    &:where(:is(h1, h2, h3, h4, h5, h6) :is(a)) {
      font-weight: inherit;
    }

    /* Inline semantics. */
    &:where(strong, b) {
      font-weight: 600;
    }
    &:where(:is(h1, h2, h3, h4) :is(strong, b)) {
      font-weight: 600;
    }
    &:where(mark) {
      background-color: color-mix(
        in oklab,
        oklch(0.86 0.17 95) 40%,
        transparent
      );
      color: inherit;
      padding: 0.05em 0.15em;
      border-radius: 0.2em;
    }
    &:where(abbr[title]) {
      text-decoration-line: underline;
      text-decoration-style: dotted;
      text-underline-offset: 0.2em;
      cursor: help;
    }
    &:where(del, s) {
      color: var(--typeset-muted);
      text-decoration-line: line-through;
    }
    &:where(sup, sub) {
      font-size: 0.75em;
      line-height: 0;
      position: relative;
      vertical-align: baseline;
    }
    &:where(sup) {
      top: -0.5em;
    }
    &:where(sub) {
      bottom: -0.25em;
    }
    &:where(sup a) {
      text-decoration-line: none;
      font-weight: 500;
    }

    /* Lists. */
    &:where(ul) {
      list-style-type: disc;
    }
    &:where(ol) {
      list-style-type: decimal;
    }
    &:where(ul ul) {
      list-style-type: circle;
    }
    &:where(ul ul ul) {
      list-style-type: square;
    }
    &:where(ol[type="a" i]) {
      list-style-type: lower-alpha;
    }
    &:where(ol[type="i" i]) {
      list-style-type: lower-roman;
    }
    &:where(ol[type="A" s]) {
      list-style-type: upper-alpha;
    }
    &:where(ol[type="I" s]) {
      list-style-type: upper-roman;
    }
    &:where(ul, ol) {
      margin-block-start: var(--typeset-flow);
      margin-block-end: 0;
      padding-inline-start: 1.5em;
    }
    &:where(li) {
      margin-block-start: 0.5em;
      padding-inline-start: 0.4em;
    }
    &:where(li > p, li > ul, li > ol) {
      margin-block-start: 0.5em;
    }
    &:where(ul > li)::marker {
      color: var(--typeset-muted);
    }
    &:where(ol > li)::marker {
      color: var(--typeset-muted);
    }

    /* GFM task lists. */
    &:where(ul.contains-task-list) {
      list-style-type: none;
      padding-inline-start: 0.25em;
    }
    &:where(li.task-list-item > input[type="checkbox"]) {
      margin-inline-end: 0.5em;
      vertical-align: -0.1em;
      accent-color: var(--color-primary, currentColor);
    }

    /* Disclosures. */
    &:where(details) {
      margin-block-start: var(--typeset-flow);
      margin-block-end: 0;
    }
    &:where(summary) {
      cursor: pointer;
      font-weight: 500;
    }
    &:where(summary)::marker {
      color: var(--typeset-muted);
    }

    /* Keyboard keys. */
    &:where(kbd) {
      font-family: inherit;
      font-size: 0.85em;
      font-weight: 500;
      border: 1px solid var(--typeset-rule);
      border-block-end-width: 2px;
      border-radius: min(calc(var(--radius, 0.5em) * 0.6), 0.35em);
      padding: 0.0625em 0.35em;
    }

    /* Definition lists. */
    &:where(dl) {
      margin-block-start: var(--typeset-flow);
      margin-block-end: 0;
    }
    &:where(dt) {
      font-weight: 500;
      margin-block-start: 1em;
    }
    &:where(dt + dt) {
      margin-block-start: 0.25em;
    }
    &:where(dd) {
      margin-block-start: 0.25em;
      margin-inline-start: 0;
      padding-inline-start: 1em;
      color: var(--typeset-muted);
    }

    /* Inline code. */
    &:where(:not(pre) > code) {
      background-color: var(
        --color-muted,
        color-mix(in oklab, currentColor 8%, transparent)
      );
      font-family: var(--typeset-font-mono);
      font-size: 0.85em;
      border-radius: min(calc(var(--radius, 0.5em) * 0.6), 0.35em);
      padding: 0.125em 0.3em;
    }

    /* Code blocks. */
    &:where(pre) {
      background-color: var(
        --color-muted,
        color-mix(in oklab, currentColor 8%, transparent)
      );
      font-family: var(--typeset-font-mono);
      font-size: 0.875em;
      line-height: 1.5;
      tab-size: 2;
      direction: ltr;
      border-radius: var(--radius, 0.5em);
      padding: 0.75em 1em;
      overflow-x: auto;
      margin-block-start: calc(var(--typeset-flow) / 0.875);
      margin-block-end: 0;
    }
    &:where(pre code) {
      background-color: transparent;
      font-family: inherit;
      font-size: inherit;
      padding: 0;
      border-radius: 0;
    }

    /* Blockquote. */
    &:where(blockquote) {
      border-inline-start: 2px solid var(--typeset-rule);
      padding-inline-start: 1em;
      margin-block-start: var(--typeset-flow);
      margin-block-end: 0;
      margin-inline: 0;
    }

    /* Dividers. */
    &:where(hr) {
      border: 0;
      border-block-start: 1px solid var(--typeset-rule);
      margin-block-start: calc(var(--typeset-flow) * 2.4);
      margin-block-end: 0;
    }
    &:where(hr + h1, hr + h2, hr + h3, hr + h4) {
      margin-block-start: var(--typeset-flow);
    }

    /* GFM footnotes. */
    &:where(.footnotes, [data-footnotes]) {
      margin-block-start: calc(var(--typeset-flow) * 2);
      border-block-start: 1px solid var(--typeset-rule);
      padding-block-start: var(--typeset-flow);
      font-size: 0.875em;
      color: var(--typeset-muted);
    }

    /* Math. */
    &:where(math[display="block"]) {
      margin-block-start: var(--typeset-flow);
      margin-block-end: 0;
      overflow-x: auto;
      overflow-y: hidden;
      padding-block: 0.25em;
    }

    /* Media. */
    &:where(img, video) {
      border-radius: var(--radius, 0.5em);
      max-width: 100%;
      height: auto;
      margin-block-start: var(--typeset-flow);
      margin-block-end: 0;
    }
    &:where(p img) {
      margin-block-start: 0;
    }
    &:where(figure) {
      margin-block-start: var(--typeset-flow);
      margin-block-end: 0;
      margin-inline: 0;
    }
    &:where(figcaption, caption) {
      color: var(--typeset-muted);
      font-size: 0.875em;
      text-align: center;
      margin-block-start: calc(0.75em / 0.875);
    }
    &:where(caption) {
      caption-side: bottom;
    }

    /* Tables. Separators sit on cells, not tr:last-child: append-safe.
       Bare tables stay real tables (keep their semantics) and wrap to fit. */
    &:where(table) {
      max-width: 100%;
      font-size: 1em;
      line-height: 1.5;
      font-variant-numeric: tabular-nums;
      border-collapse: separate;
      border-spacing: 0;
      border-block-end: 1px solid var(--typeset-rule);
      margin-block-start: var(--typeset-flow);
      margin-block-end: 0;
    }

    /* Horizontal scroll for any wide block. Wrap it and the wrapper owns the
       flow margin. Tables shrink to fit, so widen the table to make it scroll
       instead of compress. */
    &:where(.typeset-scroll) {
      overflow-x: auto;
      margin-block-start: var(--typeset-flow);
    }
    &:where(.typeset-scroll > *) {
      margin-block-start: 0;
    }
    &:where(.typeset-scroll table) {
      width: max-content;
      max-width: none;
    }
    &:where(thead th) {
      font-weight: 500;
      text-align: start;
      white-space: nowrap;
      padding: 0.65em 1em;
    }
    &:where(:is(tbody, tfoot) :is(td, th)) {
      padding: 0.75em 1em;
      text-align: start;
      vertical-align: top;
      border-block-start: 1px solid var(--typeset-rule);
    }
    &:where(tbody th, tfoot th) {
      font-weight: 500;
    }
    &:where(th:first-child, td:first-child) {
      padding-inline-start: 0;
    }
    &:where(th[align="center"], td[align="center"]) {
      text-align: center;
    }
    &:where(th[align="right"], td[align="right"]) {
      text-align: end;
    }

    /* Blocks inside list items keep the list's tighter rhythm. */
    &:where(li > blockquote, li > table, li > figure) {
      margin-block-start: 0.5em;
    }
    &:where(li > pre) {
      margin-block-start: calc(0.5em / 0.875);
    }

    @media print {
      &:where(pre, table, blockquote, figure) {
        break-inside: avoid;
      }
      &:where(h1, h2, h3, h4) {
        break-after: avoid;
      }
    }

    /* Forced colors strips the code background, so give it a border. */
    @media (forced-colors: active) {
      &:where(:not(pre) > code) {
        border: 1px solid;
      }
    }
  }

  /* First child adds no space above. Last so it wins ties. */
  .typeset
    > :where(:first-child):not(
      :where(
        .not-typeset,
        [data-not-typeset],
        .not-typeset *,
        [data-not-typeset] *
      )
    ),
  .typeset
    > :where(:first-child)
    > :where(:first-child):not(
      :where(
        .not-typeset,
        [data-not-typeset],
        .not-typeset *,
        [data-not-typeset] *
      )
    ),
  .typeset
    :where(
      li > :first-child,
      blockquote > :first-child,
      td > :first-child,
      th > :first-child,
      dd > :first-child,
      figure > :first-child,
      figure > picture > img
    ):not(
      :where(
        .not-typeset,
        [data-not-typeset],
        .not-typeset *,
        [data-not-typeset] *
      )
    ) {
    margin-block-start: 0;
  }
}

@layer components {
  .typeset-chat {
    --typeset-size: 0.875rem;
    --typeset-leading: 1.55;
    --typeset-flow: 0.75em;
  }
}

import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}
